def load_config():
    if CONFIG_FILE.exists():
        return json.loads(CONFIG_FILE.read_text())
    return {}

def save_config(cfg):
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    CONFIG_FILE.write_text(json.dumps(cfg, indent=2))

def get_headers(token, referer=None):
    return {
        "accept": "*/*",
        "accept-language": "en-US,en;q=0.9",
        "authorization": f"Bearer {token}",
        "x-client-platform": "web",
        "x-client-version": "1.3.0-auto-resume",
        "x-app-version": "20241129.1",
        "x-client-locale": "en_US",
        "sec-ch-ua": '"Not)A;Brand";v="8", "Chromium";v="138", "Brave";v="138"',
        "sec-fetch-dest": "empty",
        "sec-fetch-mode": "cors",
        "sec-fetch-site": "same-origin",
        "priority": "u=1, i",
        "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    }

# ---------- POW ----------
def solve_pow(token, target_path, session_id=None):
    """Calls node pow_solver.js with challenge data and returns base64 header."""
    headers = get_headers(token, referer=f"{BASE_URL}/a/chat/s/{session_id}" if session_id else None)
    resp = cffi_requests.post(
        f"{BASE_URL}/api/v0/chat/create_pow_challenge",
        headers=headers,
        json={"target_path": target_path},
        impersonate="chrome110"
    )
    data = resp.json()["data"]["biz_data"]["challenge"]
    # pass only the fields needed by the solver
    solver_input = {
        "challenge": data["challenge"],
        "salt": data["salt"],
        "expire_at": data["expire_at"],
        "difficulty": data["difficulty"]
    }
    proc = subprocess.run(
        ["node", str(WASM_SOLVER)],
        input=json.dumps(solver_input),
        capture_output=True, text=True, timeout=30
    )
    if proc.returncode != 0:
        raise RuntimeError(f"PoW solver failed: {proc.stderr}")
    answer = int(proc.stdout.strip())
    payload = {
        "algorithm": data["algorithm"],
        "challenge": data["challenge"],
        "salt": data["salt"],
        "answer": answer,
        "signature": data["signature"],
        "target_path": data["target_path"]
    }
    return base64.b64encode(json.dumps(payload).encode()).decode()

# ---------- SESSION ----------
def create_session(token):
    headers = get_headers(token)
