# ---------- FILE UPLOAD ----------
def upload_file(token, file_path, session_id=None):
    pow_header = solve_pow(token, "/api/v0/file/upload_file", session_id)
    headers = get_headers(token, referer=f"{BASE_URL}/a/chat/s/{session_id}" if session_id else None)
    headers["x-ds-pow-response"] = pow_header
    headers.pop("content-type", None)  # let curl_cffi set multipart
    with open(file_path, "rb") as f:
        resp = cffi_requests.post(
