                search_enabled = True
            elif val in ['off', 'false', '0']:
                search_enabled = False
            else:
                console.print("[red]Use /search on|off[/]")
            time.sleep(0.3)
            continue

        if user_input.lower().startswith('/model '):
            val = user_input.split()[1].lower()
            if val in ['expert', 'pro']:
                model_mode = 'expert'
            elif val in ['instant', 'default']:
                model_mode = 'instant'
            else:
                console.print("[red]Use /model instant|expert[/]")
            console.print(f"[yellow]Model set to {model_mode}. (API wiring pending)[/]")
            time.sleep(0.3)
            continue

        if user_input.lower().startswith('/attach '):
            filepath = user_input[7:].strip().strip('"').strip("'")
            if not filepath:
                console.print("[red]Usage: /attach <file>[/]")
                continue
            expanded = Path(filepath).expanduser()
            console.print(f"[yellow]Uploading {expanded}...[/]")
            fid = upload_file(token, sid, str(expanded))
            if fid:
                wait_for_file(token, fid)
                attached_file_id = fid
                attached_filename = expanded.name
                console.print(f"[green]File attached: {attached_filename}[/]")
            else:
                console.print("[red]Upload failed.[/]")
            time.sleep(0.5)
            continue

        if user_input.lower() == '/clear-attach':
            attached_file_id = None
            attached_filename = None
            console.print("[green]Attachment cleared.[/]")
            time.sleep(0.3)
            continue

        if not user_input:
            continue

        console.print("[yellow]Sending...[/]")
        actual_parent = parent_id
        if actual_parent is None:
            assistants = [m for m in messages if m.get("role","").upper() == "ASSISTANT"]
            if assistants:
                actual_parent = assistants[-1]["message_id"]

        file_ids = [attached_file_id] if attached_file_id else []
        stream_completion(token, user_input, sid, actual_parent,
                          thinking=thinking_enabled,
                          search=search_enabled,
                          file_ids=file_ids)
        console.print()

        attached_file_id = None
        attached_filename = None

if __name__ == "__main__":
    main()
